From ddda373eb529035db3b6b54433523853368ef05d Mon Sep 17 00:00:00 2001
From: Nick Wellnhofer <wellnhofer@aevum.de>
Date: Tue, 6 Feb 2024 12:53:03 +0100
Subject: [PATCH] xmlreader: Make xmlTextReaderValidateEntity return an error
 code

This makes sure that xmlTextReaderRead returns -1 if a memory
allocation fails.
---
 xmlreader.c | 13 ++++++++-----
 1 file changed, 8 insertions(+), 5 deletions(-)

diff --git a/xmlreader.c b/xmlreader.c
index 6486c7d..9cd0175 100644
--- a/xmlreader.c
+++ b/xmlreader.c
@@ -1004,7 +1004,7 @@ xmlTextReaderValidatePop(xmlTextReaderPtr reader) {
  * entity substitution is not activated. As a result the parser interface
  * must walk through the entity and do the validation calls
  */
-static void
+static int
 xmlTextReaderValidateEntity(xmlTextReaderPtr reader) {
     xmlNodePtr oldnode = reader->node;
     xmlNodePtr node = reader->node;
@@ -1033,7 +1033,7 @@ xmlTextReaderValidateEntity(xmlTextReaderPtr reader) {
 	} else if (node->type == XML_ELEMENT_NODE) {
 	    reader->node = node;
 	    if (xmlTextReaderValidatePush(reader) < 0)
-                return;
+                return(-1);
 	} else if ((node->type == XML_TEXT_NODE) ||
 		   (node->type == XML_CDATA_SECTION_NODE)) {
             xmlTextReaderValidateCData(reader, node->content,
@@ -1049,7 +1049,7 @@ xmlTextReaderValidateEntity(xmlTextReaderPtr reader) {
 	    continue;
 	} else if (node->type == XML_ELEMENT_NODE) {
 	    if (xmlTextReaderValidatePop(reader) < 0)
-                return;
+                return(-1);
 	}
 skip_children:
 	if (node->next != NULL) {
@@ -1071,7 +1071,7 @@ skip_children:
 		}
 		reader->node = node;
 		if (xmlTextReaderValidatePop(reader) < 0)
-                    return;
+                    return(-1);
 	    }
 	    if ((node->type == XML_ENTITY_DECL) &&
 		(reader->ent != NULL) && (reader->ent->children == node)) {
@@ -1086,6 +1086,8 @@ skip_children:
 	} while ((node != NULL) && (node != oldnode));
     } while ((node != NULL) && (node != oldnode));
     reader->node = oldnode;
+
+    return(0);
 }
 #endif /* LIBXML_REGEXP_ENABLED */

@@ -1486,7 +1488,8 @@ node_found:
     } else if ((reader->node != NULL) &&
 	       (reader->node->type == XML_ENTITY_REF_NODE) &&
 	       (reader->ctxt != NULL) && (reader->validate)) {
-	xmlTextReaderValidateEntity(reader);
+	if (xmlTextReaderValidateEntity(reader) < 0)
+            return(-1);
 #endif /* LIBXML_REGEXP_ENABLED */
     }
     if ((reader->node != NULL) &&
-- 
